//! llguidance backend for tool-call grammars.
//!
//! llama.cpp's GBNF sampler decides token validity by walking every
//! candidate's text through every live parse stack. llguidance instead keeps
//! a lexer DFA and a token trie, so one mask costs a trie walk with shared
//! prefixes. Its masks are bit vectors, and checking one sampled token is a
//! single `validate_tokens` call.
//!
//! The tool grammars are lazy: they only constrain output after the trigger
//! token (`<tool_call>`, `[TOOL_CALLS]`). llguidance has no lazy mode, so
//! [`LlgToolGrammar`] watches the generated bytes for the trigger itself and
//! then starts a matcher whose grammar describes what follows the trigger.
//! The trigger may be one special token or several ordinary ones; bytes of
//! the triggering token that follow the trigger are fed to the matcher.
//! The Lark text itself is generated in [`super::lark`].

pub(crate) use super::lark::Tier;
use super::lark::{self, Delim};
use crate::chat_format::ToolFormat;
use crate::common_chat::ToolGrammar;
use llama_cpp_2::model::LlamaModel;
use llama_cpp_2::sampling::LlamaSampler;
use llama_cpp_2::token::LlamaToken;
use llama_cpp_2::token::data_array::LlamaTokenDataArray;
use llguidance::api::TopLevelGrammar;
use llguidance::{Matcher, ParserFactory};
use querymt::chat::Tool;
use std::sync::{Arc, Mutex, Weak};
use toktrie::TokEnv;

/// Per-model llguidance state. Building the token trie walks the whole
/// vocabulary (hundreds of ms), so it is done once per loaded model. The
/// most recent compiled grammars are kept too: an agent sends the same
/// tool list on every request.
struct ModelEnv {
    model: Weak<LlamaModel>,
    factory: ParserFactory,
    grammars: Vec<(String, Matcher)>,
}

const GRAMMAR_CACHE: usize = 8;

static ENVS: Mutex<Vec<ModelEnv>> = Mutex::new(Vec::new());

/// Log a fallback from llguidance (to a coarser grammar or to GBNF). Each
/// fallback happens at most once per request.
pub(crate) fn note_fallback(message: std::fmt::Arguments<'_>) {
    log::warn!("{message}");
    #[cfg(test)]
    test_hooks::FALLBACKS.with(|count| count.set(count.get() + 1));
}

fn with_env<T>(model: &Arc<LlamaModel>, f: impl FnOnce(&mut ModelEnv) -> T) -> Result<T, String> {
    let mut envs = ENVS.lock().unwrap_or_else(|e| e.into_inner());
    envs.retain(|env| env.model.strong_count() > 0);
    let pos = envs
        .iter()
        .position(|env| env.model.upgrade().is_some_and(|m| Arc::ptr_eq(&m, model)));
    let index = match pos {
        Some(index) => index,
        None => {
            let tok_env = LlamaSampler::llguidance_tok_env(model);
            let mut factory = ParserFactory::new_simple(&tok_env)
                .map_err(|e| format!("failed to initialize llguidance: {e}"))?;
            factory.quiet();
            envs.push(ModelEnv {
                model: Arc::downgrade(model),
                factory,
                grammars: Vec::new(),
            });
            envs.len() - 1
        }
    };
    Ok(f(&mut envs[index]))
}

impl ModelEnv {
    fn matcher(&mut self, lark: &str) -> Result<Matcher, String> {
        if let Some((_, matcher)) = self.grammars.iter().find(|(g, _)| g == lark) {
            return Ok(matcher.deep_clone());
        }
        let parser = self
            .factory
            .create_parser(TopLevelGrammar::from_lark(lark.to_string()));
        let matcher = Matcher::new(parser);
        if let Some(error) = matcher.get_error() {
            return Err(error);
        }
        if self.grammars.len() >= GRAMMAR_CACHE {
            self.grammars.remove(0);
        }
        self.grammars.push((lark.to_string(), matcher.deep_clone()));
        Ok(matcher)
    }
}

/// Lazy tool-call constraint backed by llguidance.
pub(crate) struct LlgToolGrammar {
    tier: Tier,
    template: Matcher,
    tok_env: TokEnv,
    trigger: Vec<u8>,
    /// Recent output bytes while waiting for the trigger.
    tail: Vec<u8>,
    active: Option<Matcher>,
    /// First matcher error; once set the matcher is no longer used and the
    /// owner is expected to switch engines.
    error: Option<String>,
}

impl LlgToolGrammar {
    /// Build the constraint for `grammar`. `Ok(None)` means llguidance has
    /// no port for this format or trigger; the caller should use GBNF.
    pub(crate) fn build(
        model: &Arc<LlamaModel>,
        grammar: &ToolGrammar,
        tools: &[Tool],
    ) -> Result<Option<Self>, String> {
        #[cfg(test)]
        if test_hooks::FORCE_BUILD_ERROR.with(std::cell::Cell::get) {
            return Err("llguidance build forced to fail by a test".into());
        }
        if !grammar.lazy || grammar.triggers.len() != 1 {
            return Ok(None);
        }
        let trigger = grammar.triggers[0].value.as_bytes().to_vec();
        if trigger.is_empty() {
            return Ok(None);
        }
        with_env(model, |env| {
            let tok_env = env.factory.tok_env().clone();
            let tag = |text: &str| -> Delim {
                match model
                    .vocab()
                    .tokenize(text.as_bytes(), false, true)
                    .as_slice()
                {
                    [token] if tok_env.tok_trie().is_special_token(token.0 as u32) => {
                        Delim::special(token.0 as u32, text)
                    }
                    _ => Delim::literal(text),
                }
            };
            let generate = |tier| match grammar.format {
                ToolFormat::Qwen3 => lark::qwen3_lark(tools, &tag, tier),
                ToolFormat::QwenFunction => lark::qwen_function_lark(tools, &tag, tier),
                ToolFormat::Ministral3 => lark::ministral_lark(tools, &tag, tier),
                ToolFormat::Lfm2 => lark::lfm2_lark(tools, &tag, tier),
                ToolFormat::FunctionGemma => lark::function_gemma_lark(tools, &tag, tier),
                ToolFormat::Gemma4 => lark::gemma4_lark(tools, &tag, tier),
            };
            let Some(schema_lark) = generate(Tier::Schema) else {
                return Ok(None);
            };
            let (template, tier) = match env.matcher(&schema_lark) {
                Ok(matcher) => (matcher, Tier::Schema),
                Err(error) => {
                    // Retrying an identical grammar cannot succeed.
                    let Some(generic) = generate(Tier::Generic).filter(|g| *g != schema_lark)
                    else {
                        return Err(error);
                    };
                    note_fallback(format_args!(
                        "llguidance schema grammar failed ({error}); using the generic grammar"
                    ));
                    (env.matcher(&generic)?, Tier::Generic)
                }
            };
            Ok(Some(Self {
                tier,
                template,
                tok_env,
                trigger,
                tail: Vec::new(),
                active: None,
                error: None,
            }))
        })?
    }

    /// Which grammar tier is enforced.
    pub(crate) fn tier(&self) -> Tier {
        self.tier
    }

    fn fail(&mut self, error: impl std::fmt::Display) {
        self.error.get_or_insert_with(|| error.to_string());
    }

    /// The matcher error that disabled this grammar, if any.
    pub(crate) fn failure(&self) -> Option<&str> {
        self.error.as_deref()
    }

    /// Simulate a matcher error (tests).
    #[cfg(test)]
    pub(crate) fn inject_error(&mut self) {
        self.fail("error injected by a test");
    }

    fn live(&mut self) -> Option<&mut Matcher> {
        if self.error.is_some() {
            None
        } else {
            self.active.as_mut()
        }
    }

    /// Whether the grammar allows `token` next. Cheap: one token.
    pub(crate) fn allows(&mut self, token: LlamaToken) -> bool {
        let Some(matcher) = self.live() else {
            return true;
        };
        match matcher.validate_tokens(&[token.0 as u32]) {
            Ok(n) => n == 1,
            Err(error) => {
                self.fail(error);
                true
            }
        }
    }

    /// Mask every candidate the grammar does not allow.
    pub(crate) fn apply(&mut self, candidates: &mut LlamaTokenDataArray) {
        let Some(matcher) = self.live() else {
            return;
        };
        match matcher.compute_mask_or_eos() {
            Ok(mask) => {
                for item in &mut candidates.data {
                    if !mask.is_allowed(item.id().0 as u32) {
                        item.set_logit(f32::NEG_INFINITY);
                    }
                }
            }
            Err(error) => self.fail(error),
        }
    }

    pub(crate) fn accept(&mut self, token: LlamaToken) {
        if self.error.is_some() {
            return;
        }
        match self.active.as_mut() {
            None => self.watch_for_trigger(token),
            Some(matcher) => {
                if matcher.is_stopped() {
                    return;
                }
                if let Err(error) = matcher.consume_token(token.0 as u32) {
                    self.fail(error);
                }
            }
        }
    }
}

impl LlgToolGrammar {
    /// Append `token`'s text to the tail; once it contains the trigger,
    /// start the matcher and feed it whatever followed the trigger.
    fn watch_for_trigger(&mut self, token: LlamaToken) {
        let piece = self.tok_env.tok_trie().decode_ext(&[token.0 as u32], true);
        self.tail.extend_from_slice(&piece);
        let Some(pos) = self
            .tail
            .windows(self.trigger.len())
            .position(|w| w == self.trigger.as_slice())
        else {
            // Keep only what could still begin a trigger.
            let keep = self.trigger.len().saturating_sub(1);
            if self.tail.len() > keep {
                self.tail.drain(..self.tail.len() - keep);
            }
            return;
        };
        let rest = self.tail.split_off(pos + self.trigger.len());
        self.tail.clear();
        let mut matcher = self.template.deep_clone();
        if !rest.is_empty() {
            let tokens = self.tok_env.tokenize_bytes(&rest);
            if let Err(error) = matcher.consume_tokens(&tokens) {
                self.fail(error);
                return;
            }
        }
        self.active = Some(matcher);
    }
}

/// Per-thread switches and counters for tests.
#[cfg(test)]
pub(crate) mod test_hooks {
    use std::cell::Cell;

    thread_local! {
        /// Fallback messages logged on this thread.
        pub(crate) static FALLBACKS: Cell<u32> = const { Cell::new(0) };
        /// Make `LlgToolGrammar::build` fail.
        pub(crate) static FORCE_BUILD_ERROR: Cell<bool> = const { Cell::new(false) };
    }
}
